def transform(grid):
 h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
 dirs=[(1,0),(-1,0),(0,1),(0,-1)]
 # red dividers enclose the regions
 seen=set(); regs=[]; ids={}
 for r in range(h):
  for c in range(w):
   if (r,c) in seen or grid[r][c]==2: continue
   cells=[(r,c)]; seen.add((r,c)); edge=False
   for y,x in cells:
    if y in (0,h-1) or x in (0,w-1): edge=True
    for dy,dx in dirs:
     a,b=y+dy,x+dx
     if 0<=a<h and 0<=b<w and grid[a][b]!=2 and (a,b) not in seen:
      seen.add((a,b)); cells.append((a,b))
   if not edge:
    i=len(regs); regs.append(cells)
    for p in cells: ids[p]=i
 palette=set(v for row in grid for v in row)-{0,2}
 colors=[next((grid[y][x] for y,x in cells if grid[y][x]),0) for cells in regs]
 adj=[set() for _ in regs]
 for i,cells in enumerate(regs):
  for y,x in cells:
   for dy,dx in dirs:
    a,b=y+dy,x+dx
    if 0<=a<h and 0<=b<w and grid[a][b]==2:
     while 0<=a<h and 0<=b<w and grid[a][b]==2: a+=dy; b+=dx
     j=ids.get((a,b))
     if j is not None and j!=i: adj[i].add(j)
 def solve():
  unknown=[i for i,v in enumerate(colors) if not v]
  if not unknown:return True
  opts={i:palette-{colors[j] for j in adj[i]} for i in unknown}
  i=min(unknown,key=lambda i:len(opts[i]))
  for v in sorted(opts[i]):
   colors[i]=v
   if solve(): return True
  colors[i]=0
  return False
 solve()
 for i,cells in enumerate(regs):
  for y,x in cells:
   if grid[y][x]==0:out[y][x]=colors[i]
 return out

